#!/usr/bin/env bash
# Autogenerated test: runs inside a container built from each compatibility image with pacman-packages installed with
# default options (scenarios "Omitted packages" and "Omitted parallelDownloads"): nothing is installed, no sync database
# is downloaded, and no file is created. The same scenarios on an image without pacman are checked by the scenario
# fail_image_without_pacman.
set -euo pipefail

# shellcheck source=/dev/null
source dev-container-features-test-lib

not_installed() {
  ! pacman -Qq "$1" >/dev/null 2>&1
}

no_sync_databases() {
  [[ -z "$(find /var/lib/pacman/sync -mindepth 1 -print -quit)" ]]
}

no_temporary_configuration() {
  [[ -z "$(find /tmp -name 'pacman-packages.*' -print -quit)" ]]
}

check "bc (a proposals package) is not installed" not_installed bc
check "tree (a proposals package) is not installed" not_installed tree
check "no sync database was downloaded" no_sync_databases
check "no temporary configuration was created under /tmp" no_temporary_configuration

reportResults
